import Foundation
import CoreGraphics
import ImageIO
import UniformTypeIdentifiers

// Mechanical sRGB/32-bit export only. Creative edits are generated by image_gen.
let args = Array(CommandLine.arguments.dropFirst())
precondition(args.count > 0 && args.count % 2 == 0, "input/output path pairs required")
for index in stride(from: 0, to: args.count, by: 2) {
  let sourceURL = URL(fileURLWithPath: args[index])
  let outputURL = URL(fileURLWithPath: args[index + 1])
  let source = CGImageSourceCreateWithURL(sourceURL as CFURL, nil)!
  let input = CGImageSourceCreateImageAtIndex(source, 0, nil)!
  precondition(input.width == input.height, "square master required; no crop allowed")
  let space = CGColorSpace(name: CGColorSpace.sRGB)!
  let context = CGContext(data: nil, width: 512, height: 512, bitsPerComponent: 8,
    bytesPerRow: 512 * 4, space: space,
    bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue | CGBitmapInfo.byteOrder32Big.rawValue)!
  context.interpolationQuality = .high
  context.setFillColor(CGColor(red: 245.0/255.0, green: 240.0/255.0, blue: 222.0/255.0, alpha: 1))
  context.fill(CGRect(x: 0, y: 0, width: 512, height: 512))
  context.draw(input, in: CGRect(x: 0, y: 0, width: 512, height: 512))
  let final = context.makeImage()!
  let output = CGImageDestinationCreateWithURL(outputURL as CFURL, UTType.png.identifier as CFString, 1, nil)!
  CGImageDestinationAddImage(output, final, nil)
  precondition(CGImageDestinationFinalize(output), "PNG export failed")
  let bytes = try Data(contentsOf: outputURL).count
  precondition(bytes <= 1_024_000, "Play icon exceeds byte limit")
  print("Exported \(outputURL.lastPathComponent): 512x512, sRGB, \(final.bitsPerPixel)-bit, \(bytes) bytes")
}
